const RAD=Math.PI/180;
const safe=n=>Number.isFinite(n);
export function polarXY([lon,lat],radius=1737400){const rho=2*radius*Math.tan(Math.PI/4+lat*RAD/2);return[rho*Math.sin(lon*RAD),rho*Math.cos(lon*RAD)];}
export function sceneMarkup(){return `<div class="real-scene"><div class="scene-controls"><div class="scene-targets" aria-label="Dirección a explorar"><button data-scene-body="sun" aria-pressed="true">☼ Mirar hacia el Sol</button><button data-scene-body="earth" aria-pressed="false">◎ Mirar hacia la Tierra</button></div><label>Recorré las muestras reales<input data-scene-time type="range" min="0" max="24" value="0" step="1"></label><output data-scene-date></output></div><div class="real-scene-grid"><section><h3>1. ¿Hacia dónde miramos?</h3><svg data-scene-compass viewBox="0 0 460 350" role="img" aria-label="Direcciones reales hacia Sol y Tierra desde el rover; norte arriba"></svg><p>Vista desde arriba. Las líneas muestran el azimut real; no representan las distancias a los astros.</p></section><section><h3>2. ¿Qué hay en esa dirección?</h3><svg data-scene-section viewBox="0 0 600 350" role="img" aria-label="Esquema del rover, relieve angular y línea de visión en la dirección elegida"></svg><p>Esquema del horizonte calculado. El relieve y los tamaños se ilustran sin escala; no es un perfil topográfico del trayecto.</p></section></div><div data-scene-caption class="scene-verdict" role="status"></div><div class="scene-legend"><span>━━ Dirección al astro</span><span>┄┄ Límite del relieve</span><span>✓ Despeje dentro del radio</span><span>× Sin despeje confirmado</span></div></div>`;}
function rover(x,y,scale=1){return `<g transform="translate(${x} ${y}) scale(${scale})"><path d="M-25 0L-18-17H16L28 0Z" fill="#9cdae0" stroke="#efffff" stroke-width="1.5"/><circle cx="-17" cy="5" r="8" fill="#162739" stroke="#a7cad7" stroke-width="2"/><circle cx="19" cy="5" r="8" fill="#162739" stroke="#a7cad7" stroke-width="2"/><path d="M0-17V-40L15-49" fill="none" stroke="#daeff1" stroke-width="3"/><circle cx="16" cy="-50" r="4" fill="#a5ed83"/></g>`;}
function astro(body,x,y,r=19){return body==='sun'?`<g><circle cx="${x}" cy="${y}" r="${r+7}" fill="#ffce6315"/><circle cx="${x}" cy="${y}" r="${r}" fill="#ffd66d"/>${Array.from({length:8},(_,i)=>{const a=i*Math.PI/4;return `<path d="M${x+Math.cos(a)*(r+5)} ${y+Math.sin(a)*(r+5)}L${x+Math.cos(a)*(r+10)} ${y+Math.sin(a)*(r+10)}" stroke="#ffd66d" stroke-width="2"/>`;}).join('')}</g>`:`<g><circle cx="${x}" cy="${y}" r="${r+5}" fill="#6bcce31a"/><circle cx="${x}" cy="${y}" r="${r}" fill="#57b4db"/><path d="M${x-r*.7} ${y-r*.5}l${r*.7} ${-r*.15} ${r*.45} ${r*.6}-${r*.35} ${r*.55}-${r*.5} ${-r*.3}Z" fill="#b4dfa7"/></g>`;}
export function drawScene(root,result,row,body='sun'){if(!root||!row)return;const label=body==='sun'?'Sol':'Tierra',target=row[body],clear=target.status==='clear_within_sampled_radius',unknown=target.status==='unknown',color=clear?'#a4ed9e':unknown?'#a8b5cb':'#ffbd78';root.querySelector('[data-scene-time]').max=result.samples.length-1;root.querySelector('[data-scene-time]').value=result.samples.indexOf(row);root.querySelector('[data-scene-date]').textContent=row.time_utc.replace('T',' ').replace('Z',' UTC');root.querySelectorAll('[data-scene-body]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.sceneBody===body)));
 if(!safe(target.elevation_deg)||!safe(target.azimuth_deg)){root.querySelector('[data-scene-caption]').textContent='Datos insuficientes para dibujar esta dirección.';root.querySelector('[data-scene-section]').innerHTML='';return;}
 let compass='<circle cx="230" cy="177" r="125" fill="#172f44" stroke="#4a7182"/><circle cx="230" cy="177" r="82" fill="none" stroke="#426174" stroke-dasharray="3 8"/><path d="M230 40V315M92 177H368" stroke="#426174"/><text x="230" y="27" text-anchor="middle">NORTE · 0°</text><text x="392" y="182">E</text><text x="230" y="337" text-anchor="middle">SUR · 180°</text><text x="56" y="182">O</text>';
 for(const key of ['earth','sun']){const p=row[key],a=p.azimuth_deg*RAD,x=230+128*Math.sin(a),y=177-128*Math.cos(a),active=key===body,col=key==='sun'?'#ffd66d':'#7bd5ea';compass+=`<g opacity="${active?1:.48}"><path d="M230 177L${x} ${y}" stroke="${col}" stroke-width="${active?4:2}" stroke-dasharray="${p.status==='clear_within_sampled_radius'?'none':'7 5'}"/>${astro(key,x,y,17)}<text x="${Math.max(65,Math.min(365,x))}" y="${Math.max(45,Math.min(312,y+36))}" text-anchor="middle">${key==='sun'?'Sol':'Tierra'} · ${p.azimuth_deg.toFixed(1)}°</text></g>`;}
 compass+=rover(230,191,.7)+'<text x="230" y="233" text-anchor="middle">Tu rover</text>';root.querySelector('[data-scene-compass]').innerHTML=compass;
 const horizon=safe(target.clearance_deg)?target.elevation_deg-target.clearance_deg:null,el=target.elevation_deg;const relevant=[0,el,...(horizon===null?[]:[horizon])],lo=Math.min(-2,...relevant)-2,hi=Math.max(4,...relevant)+2,Y=a=>255-(a-lo)/(hi-lo)*190,origin={x:70,y:Y(0)},end={x:516,y:Y(el)},ridge={x:290,y:Y(0)+(Y(horizon??0)-Y(0))*(290-70)/(516-70)},rayAtRidge=origin.y+(end.y-origin.y)*(ridge.x-origin.x)/(end.x-origin.x);
 // Vertical placement is a schematic angular comparison, not a spatial ray trace.
 let section=`<path d="M25 ${origin.y+56}Q80 ${origin.y+43} 120 ${origin.y+54}T230 ${origin.y+49}L${ridge.x} ${ridge.y}L365 ${origin.y+50}Q440 ${origin.y+42} 575 ${origin.y+55}V340H25Z" fill="#314b60" stroke="#8aa9bc" stroke-width="2"/><path d="M${origin.x} ${origin.y}H555" stroke="#668397" stroke-dasharray="5 6"/><text x="105" y="${Math.min(324,origin.y+20)}">Horizontal local · 0°</text>`;
 if(horizon!==null){section+=`<path d="M${origin.x} ${origin.y}L${end.x} ${Y(horizon)}" stroke="#b4c4d2" stroke-dasharray="5 5" opacity=".65"/><text x="318" y="${Math.max(58,ridge.y-30)}">Relieve · ${horizon.toFixed(1)}°</text>`;}
 // Connect observer to target symbol; the verdict is supplied by the NASA/JPL case.
 section+=`<path d="M${origin.x} ${origin.y}L${end.x} ${end.y}" stroke="${color}" stroke-width="3" stroke-dasharray="${clear?'none':'8 5'}"/>${!clear&&!unknown?`<circle cx="${ridge.x}" cy="${rayAtRidge}" r="12" fill="#172537" stroke="#ffbd78"/><text x="${ridge.x}" y="${rayAtRidge+5}" text-anchor="middle" style="fill:#ffbd78">×</text>`:''}${rover(origin.x,origin.y+40,.8)}${astro(body,end.x,end.y,22)}<text x="${end.x}" y="${Math.max(31,end.y-39)}" text-anchor="middle">${label} · ${el.toFixed(1)}°</text><text x="33" y="325">OBSERVADOR · ${result.horizon.antenna_m} m sobre el suelo</text><rect x="30" y="15" width="226" height="31" rx="14" fill="#101e2c"/><text x="43" y="36" style="fill:${color}">${unknown?'? Datos insuficientes':clear?'✓ Supera el horizonte':'× Sin despeje confirmado'}</text>`;
 root.querySelector('[data-scene-section]').innerHTML=section;root.querySelector('[data-scene-caption]').innerHTML=`<b>${clear?`El ${label==='Sol'?'Sol':'astro'} supera el horizonte analizado.`:unknown?'Faltan datos para confirmar la visibilidad.':`${label}: el relieve o el margen impiden confirmar el despeje.`}</b><span>Elevación ${el.toFixed(1)}°${horizon===null?'':` · horizonte ${horizon.toFixed(1)}° · separación angular ${target.clearance_deg.toFixed(1)}°`} · margen exigido ${result.margin_deg}°. Radio analizado: ${(result.horizon.radius_m/1000).toFixed(0)} km.</span><small>Se conserva el estado calculado del caso. “Despejado” se limita al radio y las muestras del modelo; no garantiza un enlace de radio.</small>`;
}
export function drawSiteMap(canvas,terrain,cases,selected,colorForSlope){if(!canvas)return;const ctx=canvas.getContext('2d'),grid=terrain.slope_deg,w=canvas.width,h=canvas.height;grid.forEach((r,j)=>r.forEach((v,i)=>{ctx.fillStyle=colorForSlope(v);ctx.fillRect(i*w/r.length,j*h/grid.length,Math.ceil(w/r.length),Math.ceil(h/grid.length));}));const [xmin,ymin,xmax,ymax]=terrain.bounds_xy_m;cases.forEach((r,i)=>{const [x,y]=polarXY(r.site.site_lon_lat),px=(x-xmin)/(xmax-xmin)*w,py=(ymax-y)/(ymax-ymin)*h;if(px<0||px>w||py<0||py>h)return;const lx=px+(i===0?-24:24),ly=py-20;ctx.strokeStyle='#f5ffe4';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(px,py);ctx.lineTo(lx,ly);ctx.stroke();ctx.beginPath();ctx.arc(px,py,4,0,Math.PI*2);ctx.fillStyle='#f5ffe4';ctx.fill();ctx.beginPath();ctx.arc(lx,ly,i===selected?14:11,0,Math.PI*2);ctx.fillStyle=i===selected?'#efffd5':'#14283e';ctx.fill();ctx.strokeStyle='#081122';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle=i===selected?'#132a23':'#fff';ctx.font='bold 14px system-ui';ctx.textAlign='center';ctx.fillText(String.fromCharCode(65+i),lx,ly+5);});}
